# -*- coding: utf-8 -*-
from taf.ul.ettf.utils.tshark import Tshark


class CaptureCommand(object):
    def __init__(self, interfaces, msg_filter=None, capture_filter=None):
        self.interfaces = interfaces
        self.msg_filter = msg_filter
        self.capture_filter = capture_filter

    @property
    def value(self):
        tshark = Tshark()
        tshark.set_text_output_format('pdml')
        tshark.flush_output_after_each_packet()

        for i in self.interfaces:
            tshark.set_interface(i)

        if self.msg_filter is not None:
            tshark.set_filter(self.msg_filter)

        if self.capture_filter is not None:
            tshark.set_capture_filter(self.capture_filter)

        return tshark
